export interface ReviewAgentAnalysisResult {
  findings: ReviewFinding[];
  summary: string;
  furtherPassesLowYield: boolean;
  followUpReviewScore: 1 | 2 | 3;
  followUpReviewRationale: string;
  intent: ReviewAgentIntent | null;
