+  const transitioned = await env.DB
+    .prepare(
+      `UPDATE review_runs SET status = ?,
+           updated_at = ?,
+           started_at = NULL,
+           finished_at = NULL,
+           report_json = NULL,
+           markdown_summary = NULL,
+           error_code = ?,
+           error_message = ?
+       WHERE id = ? AND status = 'running' AND attempt_count = ?`
+    )
+    .bind('queued', now, 'retry_scheduled', input.message, reviewId, input.attemptCount)
+    .run();
